	CONSTRAINT `page_views_id` PRIMARY KEY(`id`)
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX `page_views_day_idx` ON `page_views` (`day`);
CREATE INDEX `page_views_path_idx` ON `page_views` (`day`,`path`);

